--region import
local Base = import("Game.UI.FightTeam.UIFightChooseCardsDialog.UIFightChooseCatBallSkillNode")
--endregion import

--region define
---@type TeamComponent
local KTool            = CS.Engine.Lib.KTool
local TeamComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.TeamComponent)
---@type CatBallUtils
local CatBallUtils = import("Game.CatBall.CatBallUtils")
local SkillStatus = {
    Lock   = 1,
    Add    = 2,
    Normal = 3,
}
--endregion define

---@class FightTeamPresetCatBallSkillNode
local FightTeamPresetCatBallSkillNode = Class("FightTeamPresetCatBallSkillNode", Base)

--region lifecycle

function FightTeamPresetCatBallSkillNode:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end
--endregion lifecycle

--region override
---覆写父类方法, 使用teamType获取数据
---@param teamType Constants.TeamMemberNumType
---@param teamIndex integer
---@param cb function 点击回调
function FightTeamPresetCatBallSkillNode:FreshUI(teamType, teamIndex, cb)
    local teamCats = TeamComponent:GetTeamCatByTeamType(teamType, teamIndex)
    local isUnlock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id3007)
    self._isUnlock = isUnlock
    self._teamType = teamType
    self._teamIndex = teamIndex
    self._cb = cb
    for index, value in ipairs(teamCats) do
        local skillType = value.catType
        local status = self:GetStatus(value, isUnlock)
        local statusComponent = self._skillType2StatusComponent[skillType]
        for key, component in pairs(statusComponent) do
            KTool.SetActive(component.gameObject, key == status)
        end

        if status == SkillStatus.Normal then
            local catId = value.catId
            ---@type CatBallVo
            local vo   = CatBallUtils.GetCatBallVo(catId)
            local icon = self._skillType2Icon[skillType]
            icon:LoadSprite(vo.picture)
        end

    end
end

---覆写父类方法, 使用teamType开启页面
function FightTeamPresetCatBallSkillNode:ToChooseCat(catBallType)
    if self._cb then
        self._cb()
    end
    CfUtils.DialogOpen(
            Constants.UITypeIds.CatBallChooseCardsDialog,
            {teamNumType = self._teamType, teamIndex = self._teamIndex, teamType = Constants.EditTeamCatType.PreFight, catBallType = catBallType},
            {{id = Constants.UITypeIds.FightTeamPresetDialog}}, true
    )
end
--endregion override

return FightTeamPresetCatBallSkillNode